import psutil
from datetime import datetime

class ProcessManager:
    """
    Manages system process operations and information retrieval.

    This class handles all process-related operations including:
    - Retrieving process information
    - Building process trees
    - Filtering processes based on various criteria
    - Process termination
    """

    def __init__(self):
        """Initialize the ProcessManager."""
        self.process_list = []

    def get_processes(self, sort_by='cpu', tree_view=False):
        processes = []
        process_dict = {}

        try:
            for proc in psutil.process_iter(['pid', 'name', 'cpu_percent', 'memory_percent', 'status', 'ppid']):
                try:
                    pinfo = proc.info
                    pinfo['cpu_percent'] = proc.cpu_percent()
                    pinfo['memory_percent'] = proc.memory_percent()
                    pinfo['ppid'] = proc.ppid()
                    pinfo['level'] = 0  # Will be set properly if tree_view is enabled
                    pinfo['children'] = []
                    process_dict[pinfo['pid']] = pinfo
                except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                    continue
        except Exception as e:
            print(f"Error getting process list: {e}")
            return []

        if tree_view:
            # Build process tree
            for pid, pinfo in process_dict.items():
                ppid = pinfo['ppid']
                if ppid in process_dict:
                    process_dict[ppid]['children'].append(pid)

            # Calculate levels and create tree-ordered list
            def add_to_tree(pid, level=0):
                if pid not in process_dict:
                    return
                process = process_dict[pid]
                process['level'] = level
                processes.append(process)
                for child_pid in sorted(process['children']):
                    add_to_tree(child_pid, level + 1)

            # Start with init process (usually PID 1) and processes without parent
            root_pids = [pid for pid, proc in process_dict.items() 
                        if proc['ppid'] not in process_dict or pid == 1]
            for pid in sorted(root_pids):
                add_to_tree(pid)
        else:
            processes = list(process_dict.values())

        # Sort processes based on criteria
        if sort_by == 'cpu':
            processes.sort(key=lambda x: x['cpu_percent'], reverse=True)
        elif sort_by == 'mem':
            processes.sort(key=lambda x: x['memory_percent'], reverse=True)
        elif sort_by == 'pid':
            processes.sort(key=lambda x: x['pid'])
        elif sort_by == 'name':
            processes.sort(key=lambda x: x['name'].lower())

        return processes

    def filter_processes(self, processes, search_term="", status=None, min_cpu=None, min_memory=None, user_filter=None):
        filtered = processes

        # Apply text search filter
        if search_term:
            filtered = [p for p in filtered if search_term.lower() in p['name'].lower() or 
                       str(p['pid']) == search_term]

        # Apply status filter
        if status:
            filtered = [p for p in filtered if p['status'] == status]

        # Apply CPU threshold filter
        if min_cpu is not None:
            filtered = [p for p in filtered if p['cpu_percent'] >= min_cpu]

        # Apply memory threshold filter
        if min_memory is not None:
            filtered = [p for p in filtered if p['memory_percent'] >= min_memory]

        # Apply user filter
        if user_filter is not None:
            try:
                filtered = [p for p in filtered if psutil.Process(p['pid']).username() == user_filter]
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                pass

        return filtered

    def get_process_details(self, pid):
        try:
            proc = psutil.Process(pid)
            return {
                'pid': pid,
                'name': proc.name(),
                'status': proc.status(),
                'cpu_percent': proc.cpu_percent(),
                'memory_percent': proc.memory_percent(),
                'create_time': datetime.fromtimestamp(proc.create_time()).strftime('%Y-%m-%d %H:%M:%S'),
                'username': proc.username(),
                'cmdline': ' '.join(proc.cmdline())
            }
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            return None

    def terminate_process(self, pid):
        """Terminate a process by PID"""
        try:
            process = psutil.Process(pid)
            process.terminate()
            return True, "Process terminated successfully"
        except psutil.NoSuchProcess:
            return False, "Process not found"
        except psutil.AccessDenied:
            return False, "Permission denied: Cannot terminate process"
        except Exception as e:
            return False, f"Error terminating process: {str(e)}"

import psutil
import os

def get_size_str(bytes):
    """Convert bytes to human readable string"""
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if bytes < 1024:
            return f"{bytes:.1f}{unit}"
        bytes /= 1024
    return f"{bytes:.1f}PB"

def get_permissions():
    """Check if we have sufficient permissions"""
    try:
        return os.geteuid() == 0
    except AttributeError:
        return False

def format_time(seconds):
    """Format seconds into readable time string"""
    minutes, seconds = divmod(int(seconds), 60)
    hours, minutes = divmod(minutes, 60)
    days, hours = divmod(hours, 24)

    if days > 0:
        return f"{days}d {hours}h"
    elif hours > 0:
        return f"{hours}h {minutes}m"
    elif minutes > 0:
        return f"{minutes}m {seconds}s"
    else:
        return f"{seconds}s"

def get_system_info():
    """Get system resource information"""
    cpu_percent = psutil.cpu_percent(interval=1)
    memory = psutil.virtual_memory()
    swap = psutil.swap_memory()

    return {
        'cpu_percent': cpu_percent,
        'memory_used': get_size_str(memory.used),
        'memory_total': get_size_str(memory.total),
        'memory_percent': memory.percent,
        'swap_used': get_size_str(swap.used),
        'swap_total': get_size_str(swap.total),
        'swap_percent': swap.percent
    }

import curses

def handle_input(key, state):
    selected_idx = state['selected_idx']
    process_count = state['process_count']
    search_term = state['search_term']
    sort_by = state['sort_by']
    filters = state['filters']
    input_mode = state['input_mode']

    # Get the current process if needed
    current_process = None
    if process_count > 0 and selected_idx >= 0:
        current_process = state.get('processes', [])[selected_idx] if state.get('processes') else None

    # Navigation
    if input_mode == 'normal':
        if key == curses.KEY_UP and selected_idx > 0:
            state['selected_idx'] = selected_idx - 1
        elif key == curses.KEY_DOWN and selected_idx < process_count - 1:
            state['selected_idx'] = selected_idx + 1
        elif key == ord('\n'):  # Enter key
            if current_process:
                state['input_mode'] = 'details'
        elif key == ord('x'):
            if current_process:
                state['input_mode'] = 'confirm_terminate'

        # Quit
        elif key in (ord('q'), ord('Q')):
            return None

        # Search mode
        elif key == ord('/'):
            state['input_mode'] = 'search'
            state['search_term'] = ""

        # Sort modes
        elif key in (ord('s'), ord('S')):
            sort_options = ['cpu', 'mem', 'pid', 'name']
            current_idx = sort_options.index(sort_by if sort_by in sort_options else sort_options[0])
            state['sort_by'] = sort_options[(current_idx + 1) % len(sort_options)]

        # Filter controls
        elif key == ord('f'):
            state['input_mode'] = 'filter_menu'
        elif key == ord('c'):
            state['filters'] = {'status': None, 'min_cpu': None, 'min_memory': None, 'user_filter': None}
        elif key == ord('t'):
            state['tree_view'] = not state['tree_view']
            state['selected_idx'] = 0  # Reset selection when switching views

    # Search input mode
    elif input_mode == 'search':
        if key in (curses.KEY_BACKSPACE, 127):
            state['search_term'] = search_term[:-1]
        elif key == 27:  # ESC
            state['input_mode'] = 'normal'
        elif 32 <= key <= 126:
            state['search_term'] = search_term + chr(key)

    # Filter menu mode
    elif input_mode == 'filter_menu':
        if key == 27:  # ESC
            state['input_mode'] = 'normal'
        elif key in (ord('1'), ord('2'), ord('3'), ord('4')):
            state['input_mode'] = f'filter_{chr(key)}'
        elif key == ord('c'):  # Clear filters
            state['filters'] = {'status': None, 'min_cpu': None, 'min_memory': None, 'user_filter': None}
            state['input_mode'] = 'normal'

    # Filter input modes
    elif input_mode.startswith('filter_'):
        if key == 27:  # ESC
            state['input_mode'] = 'normal'
        elif key == ord('\n'):  # Enter
            state['input_mode'] = 'normal'

        # Status filter
        elif input_mode == 'filter_1':
            if key in (ord('r'), ord('s'), ord('t'), ord('z')):
                state['filters']['status'] = {
                    'r': 'running',
                    's': 'sleeping',
                    't': 'stopped',
                    'z': 'zombie'
                }[chr(key)]
                state['input_mode'] = 'normal'

        # CPU/Memory threshold filters
        elif input_mode in ('filter_2', 'filter_3'):
            if key in (curses.KEY_BACKSPACE, 127):
                filter_key = 'min_cpu' if input_mode == 'filter_2' else 'min_memory'
                current = filters.get(filter_key, '')
                if current:
                    new_value = str(current)[:-1]
                    try:
                        state['filters'][filter_key] = float(new_value) if new_value else None
                    except ValueError:
                        pass
            elif 48 <= key <= 57 or key == ord('.'):  # Numbers and decimal point
                filter_key = 'min_cpu' if input_mode == 'filter_2' else 'min_memory'
                current = filters.get(filter_key, '')
                new_value = str(current if current is not None else '') + chr(key)
                try:
                    value = float(new_value)
                    state['filters'][filter_key] = value
                except ValueError:
                    pass

        # Username filter
        elif input_mode == 'filter_4':
            if key in (curses.KEY_BACKSPACE, 127):
                current = filters.get('user_filter', '')
                state['filters']['user_filter'] = current[:-1] if current else None
            elif 32 <= key <= 126:  # Printable characters
                current = filters.get('user_filter', '')
                state['filters']['user_filter'] = (current if current else '') + chr(key)

    # Process details mode
    elif input_mode == 'details':
        if key in (27, ord('q')):  # ESC or 'q'
            state['input_mode'] = 'normal'

    # Confirmation dialog mode
    elif input_mode == 'confirm_terminate':
        if key == ord('y'):
            if current_process:
                success, message = state['process_manager'].terminate_process(current_process['pid'])
                state['status_message'] = message
            state['input_mode'] = 'normal'
        elif key in (ord('n'), 27):  # 'n' or ESC
            state['input_mode'] = 'normal'

    return state
